#!/usr/bin/env python3
import r2pipe
import sys

def analyze_binary():
    r2 = r2pipe.open('./program')
    r2.cmd('aaa')  # Analyze all

    # Get main function disassembly
    main_disasm = r2.cmd('pdf @ main')

    # Parse the disassembly for important instructions
    mov_instructions = []
    imul_instructions = []

    for line in main_disasm.split('\n'):
        if 'mov' in line:
            mov_instructions.append(line.strip())
        elif 'imul' in line:
            imul_instructions.append(line.strip())

    print("=== MOV Instructions ===")
    for instr in mov_instructions:
        print(instr)

    print("\n=== IMUL Instructions ===")
    for instr in imul_instructions:
        print(instr)

    r2.quit()

if __name__ == '__main__':
    analyze_binary()

import struct

# Define the hex constants
constants = [0x014BE74F, 0x77CF4B64, 0x182265E9, 0x8DAAAD]

def analyze_constant(c):
    # Convert to bytes in little endian
    b = c.to_bytes((c.bit_length() + 7) // 8, 'little')
    # Try to decode as ASCII, ignore non-printable
    try:
        ascii_str = ''.join(chr(x) if 32 <= x <= 126 else '.' for x in b)
    except:
        ascii_str = 'non-printable'
    print(f"\nConstant: {hex(c)}")
    print(f"Decimal: {c}")
    print(f"Bytes: {b}")
    print(f"ASCII: {ascii_str}")
    print(f"Factors: {get_factors(c)}")

def get_factors(n):
    factors = []
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            factors.append(i)
            if i != n // i:
                factors.append(n // i)
    return sorted(factors)

print("Analyzing provided constants:")
for c in constants:
    analyze_constant(c)

# Read and parse the assembly bytes
with open('program.txt', 'r') as f:
    bytes_str = f.read().strip()

bytes_list = [int(x.strip()) for x in bytes_str.split(',')]
print("\nProgram analysis:")
print(f"Total bytes: {len(bytes_list)}")

# Look for common assembly patterns
def find_patterns():
    patterns = {
        'mov': [0x48, 0x89],  # mov reg,reg
        'mul': [0x48, 0x0F, 0xAF],  # imul reg,reg
        'cmp': [0x48, 0x39],  # cmp reg,reg
        'jmp': [0xE9],  # jmp
        'call': [0xE8]  # call
    }

    print("\nCommon instruction patterns found:")
    for name, pattern in patterns.items():
        count = 0
        for i in range(len(bytes_list) - len(pattern)):
            if bytes_list[i:i+len(pattern)] == pattern:
                count += 1
        print(f"{name}: {count} occurrences")

find_patterns()

# Look for strings
string_bytes = []
current_string = []
for b in bytes_list:
    if 32 <= b <= 126:  # printable ASCII
        current_string.append(b)
    elif len(current_string) >= 4:  # minimum string length
        string_bytes.append(bytes(current_string))
        current_string = []
    else:
        current_string = []

if string_bytes:
    print("\nPossible strings found:")
    for s in string_bytes:
        try:
            print(s.decode('ascii'))
        except:
            pass
